BN_DIGITS = "০১২৩৪৫৬৭৮৯"

def bn_num(n):
    return "".join(BN_DIGITS[int(c)] for c in str(n))

def bn_num_tex(n):
    return r'{\bn ' + bn_num(n) + r'}'

def esc(s):
    if s is None:
        return "---"
    s = str(s)
    repl = [
        ("\\", r"\textbackslash{}"), ("&", r"\&"), ("%", r"\%"), ("$", r"\$"),
        ("#", r"\#"), ("_", r"\_"), ("{", r"\{"), ("}", r"\}"),
        ("~", r"\textasciitilde{}"), ("^", r"\textasciicircum{}"),
        ("\u2018", "'"), ("\u2019", "'"), ("\u201c", "``"), ("\u201d", "''"),
    ]
    for a, b in repl:
        s = s.replace(a, b)
    return s

_LAT_RE = re.compile(r"([A-Za-z][A-Za-z0-9 .,'\-/&()]*)")

def tex_text(s):
    s = esc(s)
    return _LAT_RE.sub(lambda m: r"{\lat " + m.group(1) + r"}", s)

def md_inline(s):
    s = tex_text(s)
    s = re.sub(r"\\\*\\\*(.+?)\\\*\\\*", r"\\textbf{\1}", s)
    s = re.sub(r"\*\*(.+?)\*\*", r"\\textbf{\1}", s)
    s = re.sub(r"(?<!\*)\*([^*\n]+?)\*(?!\*)", r"\1", s)
    return s

def author_block(a, n):
    out = []
    out.append(
        r"\vspace{1pt}\noindent\colorbox{authband}{\parbox{\dimexpr\linewidth-2\fboxsep\relax}{"
        r"\color{white}\bfseries\footnotesize{\bn " + bn_num(n) + r"}. "
        + tex_text(a.get('full_name', '---'))
        + r" \textnormal{\scriptsize\itshape (" + tex_text(a.get('eng_name', '---')) + r")} "
        + r"\hfill \textnormal{\scriptsize " + tex_text(a.get('hsc_text', '---')) + r"}}}\par"
    )
    pieces = []
    for label, key in FIELDS:
        raw = a.get(key, '---')
        if str(raw).strip() in ('', '\u2014', '---'):
            continue
        pieces.append(r"\textbf{" + tex_text(label) + r":}~" + tex_text(raw))
    out.append(r"{\scriptsize\justifying " + r" \;|\; ".join(pieces) + r"\par}")
    out.append(r"\vspace{1pt}")
    return "\n".join(out)

