def split_lessons(text):
    tn = unicodedata.normalize("NFC", text)
    hits = []
    for aid, key in LESSON_ANCHORS:
        kn = unicodedata.normalize("NFC", key)
        p = tn.find(kn)
        if p != -1:
            hits.append((p, aid))
    hits.sort()
    chunks = {}
    bonus = []
    if hits and hits[0][0] > 50:
        bonus.append(("prelude", text[:hits[0][0]].strip()))
    for i, (pos, aid) in enumerate(hits):
        end = hits[i + 1][0] if i + 1 < len(hits) else len(text)
        chunks[aid] = text[pos:end].strip()
    return chunks, bonus

def stub_lesson(a):
    parts = []
    if a.get('theme'):
        parts.append("**মূলভাব:** " + a['theme'])
    if a.get('source_book'):
        parts.append("**উৎস:** " + a['source_book'])
    if a.get('fame'):
        parts.append("**লেখকের পরিচয়:** " + a['fame'])
    if a.get('career'):
        parts.append("**সাহিত্যকর্ম:** " + a['career'])
    return "\n\n".join(parts) if parts else "বিস্তারিত আলোচনা পাঠ্যবই অনুযায়ী সংযোজিত হবে।"

def render_lessons_text(text):
    lines = text.split("\n")
    out = []
    in_list = False

    def close():
        nonlocal in_list
        if in_list:
            out.append(r"\end{itemize}")
            in_list = False

    for raw in lines:
        line = raw.rstrip()
        st = line.strip()
        if not st:
            close()
            continue
        if set(st) <= {"-"} and len(st) >= 3:
            close()
            out.append(r"\vspace{1pt}\hrule\vspace{1pt}")
            continue
        m = re.match(r"^####\s*\*\*(.+?)\*\*\s*$", st)
        if m:
            close()
            out.append(r"\noindent\textbf{\footnotesize " + md_inline(m.group(1)) + r"}\par")
            continue
        m = re.match(r"^###\s*\*\*(.+?)\*\*\s*$", st) or re.match(r"^###\s+(.+)$", st)
        if m:
            close()
            out.append(
                r"\smallskip\noindent\colorbox{subband}{\parbox{\dimexpr\linewidth-2\fboxsep\relax}"
                r"{\color{white}\bfseries\scriptsize " + md_inline(m.group(1)) + r"}}\par"
            )
            continue
        m = re.match(r"^\*\s+(.+)$", st)
        if m:
            if not in_list:
                out.append(r"\begin{itemize}[leftmargin=3mm,itemsep=0pt,topsep=0pt,parsep=0pt,label={{\lat\textbullet}}]")
                in_list = True
            out.append(r"\item " + md_inline(m.group(1)))
            continue
        m = re.match(r"^\*\*(.+?)\*\*\s*$", st)
        if m:
            close()
            out.append(r"\noindent\textbf{\footnotesize " + md_inline(m.group(1)) + r"}\par")
            continue
        m = re.match(r"^(\d+)\.\s+(.+)$", st)
        if m:
            close()
            out.append(r"\smallskip\noindent\textbf{" + m.group(1) + r". " + md_inline(m.group(2)) + r"}\par")
            continue
        close()
        out.append(md_inline(st) + r"\par")
    close()
    return "\n".join(out)

def lesson_section_for_author(a, n, chunks):
    work_name = a.get('hsc_text', '')
    paren_idx = work_name.find('(')
    if paren_idx > 0:
        work_base = work_name[:paren_idx].strip()
        work_type = a.get('work_type', '')
        display_title = work_base + " " + work_type
    else:
        display_title = work_name
    header = (
        r"\smallskip\noindent\colorbox{authband}{\parbox{\dimexpr\linewidth-2\fboxsep\relax}{"
        r"\color{white}\bfseries\footnotesize{\bn " + bn_num(n) + r"}. "
        + tex_text(display_title)
        + r" \textnormal{\footnotesize " + tex_text("সম্পূর্ণ বিশ্লেষণ ও গুরুত্বপূর্ণ ব্যাখ্যা") + r"}"
        + r" \hfill \textnormal{\scriptsize " + tex_text(a['full_name']) + r"}}}\par"
    )
    body_src = chunks.get(n) or stub_lesson(a)
    return header + "\n" + render_lessons_text(body_src) + r"\vspace{2pt}"

def build_lessons_block():
    chunks, bonus = split_lessons(LESSON_TEXT)
    parts = []
    for n in range(1, len(AUTHORS) + 1):
        parts.append(lesson_section_for_author(AUTHORS[n - 1], n, chunks))
    if bonus:
        for tag, txt in bonus:
            if txt.strip():
                parts.append(
                    r"\smallskip\noindent\colorbox{subband}{\parbox{\dimexpr\linewidth-2\fboxsep\relax}"
                    r"{\color{white}\bfseries\scriptsize " + tex_text("অতিরিক্ত নোট") + r"}}\par"
                )
                parts.append(render_lessons_text(txt))
    return "\n".join(parts)

